import type { OpenAPIV3, OpenAPIV3_1 } from 'openapi-types';
import type { DiscriminatorObject3_2, Schema3_2, XMLNodeType, XMLObject3_2 } from './schema.js';
type Modify<T, R> = Omit<T, keyof R> & R;
export type Document = Modify<OpenAPIV3_1.Document, {
    $self?: string;
    servers?: ServerObject[];
    paths?: PathsObject;
    webhooks?: Record<string, PathItemObject | ReferenceObject>;
    components?: ComponentsObject;
    security?: SecurityRequirementObject[];
    tags?: TagObject[];
}>;
export type ReferenceObject = OpenAPIV3_1.ReferenceObject;
export type ServerObject = Modify<OpenAPIV3_1.ServerObject, {
    name?: string;
}>;
export type HttpMethods = OpenAPIV3.HttpMethods | 'query';
export type PathsObject = Record<string, PathItemObject | undefined>;
export interface PathItemObject extends Omit<OpenAPIV3_1.PathItemObject, HttpMethods | 'servers' | 'parameters'>, Partial<Record<HttpMethods, OperationObject>> {
    servers?: ServerObject[];
    parameters?: (ReferenceObject | ParameterObject)[];
    additionalOperations?: Record<string, OperationObject>;
}
export type OperationObject = Modify<OpenAPIV3_1.OperationObject, {
    parameters?: (ReferenceObject | ParameterObject)[];
    requestBody?: ReferenceObject | RequestBodyObject;
    responses?: ResponsesObject;
    callbacks?: Record<string, ReferenceObject | CallbackObject>;
    security?: SecurityRequirementObject[];
    servers?: ServerObject[];
}>;
export type ParameterLocation = 'query' | 'querystring' | 'header' | 'path' | 'cookie';
export type ParameterStyle = 'matrix' | 'label' | 'simple' | 'form' | 'spaceDelimited' | 'pipeDelimited' | 'deepObject' | 'cookie';
export type ParameterBaseObject = Modify<OpenAPIV3.ParameterBaseObject, {
    schema?: ReferenceObject | SchemaObject;
    examples?: Record<string, ReferenceObject | ExampleObject>;
    content?: Record<string, ReferenceObject | MediaTypeObject>;
}>;
export type ParameterObject = ParameterBaseObject & {
    name: string;
    in: string;
};
export type HeaderObject = ParameterBaseObject;
export type SchemaObject = Schema3_2;
export type DiscriminatorObject = DiscriminatorObject3_2;
export type XMLObject = XMLObject3_2;
export type { XMLNodeType };
export type ExampleObject = OpenAPIV3.ExampleObject & {
    dataValue?: unknown;
    serializedValue?: string;
};
export type MediaTypeObject = Modify<OpenAPIV3_1.MediaTypeObject, {
    schema?: ReferenceObject | SchemaObject;
    itemSchema?: ReferenceObject | SchemaObject;
    examples?: Record<string, ReferenceObject | ExampleObject>;
    encoding?: Record<string, EncodingObject>;
    prefixEncoding?: EncodingObject[];
    itemEncoding?: EncodingObject;
}>;
export type EncodingObject = Modify<OpenAPIV3.EncodingObject, {
    headers?: Record<string, ReferenceObject | HeaderObject>;
    encoding?: Record<string, EncodingObject>;
    prefixEncoding?: EncodingObject[];
    itemEncoding?: EncodingObject;
}>;
export type RequestBodyObject = Modify<OpenAPIV3_1.RequestBodyObject, {
    content: Record<string, ReferenceObject | MediaTypeObject>;
}>;
export type ResponsesObject = Record<string, ReferenceObject | ResponseObject>;
export type ResponseObject = Modify<OpenAPIV3_1.ResponseObject, {
    summary?: string;
    description?: string;
    headers?: Record<string, ReferenceObject | HeaderObject>;
    content?: Record<string, ReferenceObject | MediaTypeObject>;
    links?: Record<string, ReferenceObject | LinkObject>;
}>;
export type LinkObject = Modify<OpenAPIV3_1.LinkObject, {
    server?: ServerObject;
}>;
export type CallbackObject = Record<string, PathItemObject | ReferenceObject>;
export type SecurityRequirementObject = OpenAPIV3.SecurityRequirementObject;
export type OAuthFlowsObject = OpenAPIV3.OAuth2SecurityScheme['flows'] & {
    deviceAuthorization?: {
        deviceAuthorizationUrl: string;
        tokenUrl: string;
        refreshUrl?: string;
        scopes: Record<string, string>;
    };
};
type SecuritySchemeBase = {
    deprecated?: boolean;
};
export type HttpSecurityScheme = OpenAPIV3.HttpSecurityScheme & SecuritySchemeBase;
export type ApiKeySecurityScheme = OpenAPIV3.ApiKeySecurityScheme & SecuritySchemeBase;
export type OpenIdSecurityScheme = OpenAPIV3.OpenIdSecurityScheme & SecuritySchemeBase;
export type MutualTlsSecurityScheme = {
    type: 'mutualTLS';
    description?: string;
} & SecuritySchemeBase;
export type OAuth2SecurityScheme = Modify<OpenAPIV3.OAuth2SecurityScheme, {
    flows: OAuthFlowsObject;
    oauth2MetadataUrl?: string;
}> & SecuritySchemeBase;
export type SecuritySchemeObject = HttpSecurityScheme | ApiKeySecurityScheme | OAuth2SecurityScheme | OpenIdSecurityScheme | MutualTlsSecurityScheme;
export type TagObject = OpenAPIV3.TagObject & {
    summary?: string;
    parent?: string;
    kind?: string;
};
export type ComponentsObject = Modify<OpenAPIV3_1.ComponentsObject, {
    schemas?: Record<string, SchemaObject>;
    responses?: Record<string, ReferenceObject | ResponseObject>;
    parameters?: Record<string, ReferenceObject | ParameterObject>;
    examples?: Record<string, ReferenceObject | ExampleObject>;
    requestBodies?: Record<string, ReferenceObject | RequestBodyObject>;
    headers?: Record<string, ReferenceObject | HeaderObject>;
    securitySchemes?: Record<string, ReferenceObject | SecuritySchemeObject>;
    links?: Record<string, ReferenceObject | LinkObject>;
    callbacks?: Record<string, ReferenceObject | CallbackObject>;
    pathItems?: Record<string, ReferenceObject | PathItemObject>;
    mediaTypes?: Record<string, ReferenceObject | MediaTypeObject>;
}>;
